TAL_MIN, TAL_MAX = 60.0, 120.0
PEAK_MIN = 237.0

def f2(x):
    return None if x is None else round(x, 2)

runs = {}
with open('/app/data/runs.csv') as f:
    for r in csv.DictReader(f):
        runs[r['run_id']] = r

data = {}
with open('/app/data/thermocouples.csv') as f:
    for r in csv.DictReader(f):
        run = r['run_id']; tc = r['tc_id']
        t = float(r['t_s']); temp = float(r['temp'])
        data.setdefault(run, {}).setdefault(tc, []).append((t, temp))

def analyze(run, tc):
    unit = runs[run]['temp_unit']
    pts = data[run][tc]
    # convert to C
    if unit == 'F':
        pts = [(t, (tp - 32.0) * 5.0 / 9.0) for (t, tp) in pts]
    pts.sort(key=lambda x: x[0])
    ts = [p[0] for p in pts]
    temps = [p[1] for p in pts]
    peak = max(temps)

    # TAL with linear interpolation at crossings
    tal = 0.0
    n = len(temps)
    # contributions: for each sample i, fraction of time within [t_i, t_{i+1}] above liquidus
    for i in range(n - 1):
        t0, t1 = ts[i], ts[i+1]
        a, b = temps[i], temps[i+1]
        dt = t1 - t0
        if dt <= 0:
            continue
        # solve for fraction f in [0,1] where temp = LIQ
        if a == b:
            if a >= LIQ:
                tal += dt
            else:
                pass
        else:
            f = (LIQ - a) / (b - a)
            f = max(0.0, min(1.0, f))
            if a >= LIQ:
                # from start until fraction f if b below, else full
                if b >= LIQ:
                    tal += dt
                else:
                    tal += f * dt
            else:
                # a below
                if b >= LIQ:
                    tal += (1 - f) * dt
                else:
                    pass
    # last point exact equality adds no time (instant)
    return peak, tal

out = {'ramp_limit_c_per_s': RAMP_LIMIT, 'runs': {}, 'failing_runs': []}

for run in sorted(runs):
    tcs = data.get(run, {})
    if not tcs:
        out['runs'][run] = {'tc_id': None, 'max_preheat_ramp': None, 'tal_s': None, 'peak_c': None, 'status': 'non-compliant'}
        out['failing_runs'].append(run)
        continue
    # coldest = lowest peak
    best_tc, best_peak = None, None
    for tc in sorted(tcs):
        p, tal = analyze(run, tc)
        if best_peak is None or p < best_peak:
            best_peak = p; best_tc = tc
    peak, tal = analyze(run, best_tc)

    # preheat ramp: max rise between consecutive samples where both >=40 and run is before first exceeding 140
    unit = runs[run]['temp_unit']
    pts = data[run][best_tc]
    if unit == 'F':
        pts = [(t, (tp - 32.0) * 5.0 / 9.0) for (t, tp) in pts]
    else:
        pts = [(float(t), float(tp)) for (t, tp) in pts]
    pts.sort(key=lambda x: x[0])
    maxramp = None
    first_exceed = None
    for i, (t, tp) in enumerate(pts):
        if tp > PRE:
            first_exceed = (t, tp)
            break
    for i in range(len(pts) - 1):
        t0, a = pts[i]; t1, b = pts[i+1]
        if first_exceed is not None and t1 > first_exceed[0]:
            continue  # beyond first exceed (cool-down / post)
        if a >= LOW and b >= LOW:
            # ensure this step is part of preheat: stop after first exceed; sample before/at first exceed ok
            dt = t1 - t0
            if dt > 0:
                ramp = (b - a) / dt
                if ramp is not None:
                    if maxramp is None or ramp > maxramp:
                        maxramp = ramp
    compliant = (maxramp is not None and maxramp <= RAMP_LIMIT) and (TAL_MIN <= tal <= TAL_MAX) and (peak >= PEAK_MIN)
    status = 'compliant' if compliant else 'non-compliant'
    out['runs'][run] = {'tc_id': best_tc, 'max_preheat_ramp': f2(maxramp), 'tal_s': f2(tal), 'peak_c': f2(peak), 'status': status}
    if not compliant:
        out['failing_runs'].append(run)

out['failing_runs'] = sorted(out['failing_runs'])
with open('/app/output/reflow_report.json', 'w') as f:
    json.dump(out, f, indent=2)
print(json.dumps(out, indent=2))
