from collections import defaultdict

# Load runs
def load_csv(path):
    with open(path) as f:
        return list(csv.DictReader(f))

runs = load_csv('/app/data/runs.csv')
boards = load_csv('/app/data/boards.csv')
tc_raw = load_csv('/app/data/thermocouples.csv')

# Reference tc per run
ref_tc = {}
for b in boards:
    if b['role'].strip() == 'reference':
        ref_tc[b['run_id']] = b['tc_id']

# Group thermocouples
series = defaultdict(list)
for r in tc_raw:
    series[(r['run_id'], r['tc_id'])].append((float(r['t_s']), float(r['temp'])))
for k in series:
    series[k].sort(key=lambda x: x[0])

LIQUIDUS = 227.0
RAMP_LIMIT = 1.5  # revision B supersedes
TAL_MIN, TAL_MAX = 45.0, 90.0
PEAK_MIN = 252.0
PREHEAT_HI = 140.0
PREHEAT_LO = 40.0

def f_to_c(t): return (t - 32) * 5 / 9

def compute(run_id, tc_id, unit):
    key = (run_id, tc_id)
    if key not in series or not series[key]:
        return None
    pts = series[key]
    if unit == 'F':
        pts = [(t, f_to_c(v)) for t, v in pts]
    temps = [v for t, v in pts]
    peak = max(temps)

    # TAL with linear interpolation at liquidus
    tal = 0.0
    n = len(pts)
    for i in range(n):
        t0, v0 = pts[i]
        if i + 1 < n:
            t1, v1 = pts[i+1]
            dt = t1 - t0
            if v0 >= LIQUIDUS and v1 >= LIQUIDUS:
                tal += dt
            elif v0 >= LIQUIDUS and v1 < LIQUIDUS:
                # crossing down
                frac = (LIQUIDUS - v0) / (v1 - v0)
                tal += dt * frac
            elif v0 < LIQUIDUS and v1 >= LIQUIDUS:
                # crossing up; segment fully? no, only portion above
                frac = (v1 - LIQUIDUS) / (v1 - v0)
                tal += dt * frac
            # both below: 0
    # single point at/above liquidus adds 0 duration

    # Preheat ramp: steps where both samples >= 40 C, until first exceeds 140 C.
    # The preheat phase ends at the sample where it first exceeds 140 C.
    # Count steps (consecutive pairs) where both samples are >= 40 C and the pair is within preheat.
    max_ramp = None
    # Determine preheat end index: first sample index where temp > 140 C
    preheat_end = None
    for idx, (t, v) in enumerate(pts):
        if v > PREHEAT_HI:
            preheat_end = idx
            break
    # Ramp computed over consecutive samples both >= 40 C and within preheat region.
    # Preheat = from start until first exceeds 140 C. So samples 0..preheat_end are in preheat.
    for i in range(n - 1):
        t0, v0 = pts[i]
        t1, v1 = pts[i+1]
        # both within preheat region (index <= preheat_end) and both >= 40
        if preheat_end is None:
            in_preheat = True
        else:
            in_preheat = (i <= preheat_end) and (i+1 <= preheat_end)
        if in_preheat and v0 >= PREHEAT_LO and v1 >= PREHEAT_LO:
            dt = t1 - t0
            if dt > 0:
                rate = (v1 - v0) / dt
                if max_ramp is None or rate > max_ramp:
                    max_ramp = rate

    return {
        'tc_id': tc_id,
        'max_preheat_ramp': round(max_ramp, 2) if max_ramp is not None else None,
        'tal_s': round(tal, 2),
        'peak_c': round(peak, 2),
    }

out = {'ramp_limit_c_per_s': RAMP_LIMIT, 'runs': {}, 'failing_runs': []}

for r in runs:
    run_id = r['run_id']
    unit = r['temp_unit'].strip()
    tc_id = ref_tc.get(run_id)
    if tc_id is None:
        # no reference thermocouple -> no data
        out['runs'][run_id] = {'tc_id': None, 'max_preheat_ramp': None, 'tal_s': None, 'peak_c': None, 'status': 'non-compliant'}
        out['failing_runs'].append(run_id)
