        out['failing_runs'].append(run_id)
        continue
    # status
    compliant = True
    if res['max_preheat_ramp'] is not None and res['max_preheat_ramp'] > RAMP_LIMIT + 1e-9:
        compliant = False
    if not (TAL_MIN - 1e-9 <= res['tal_s'] <= TAL_MAX + 1e-9):
        compliant = False
    if res['peak_c'] is not None and res['peak_c'] < PEAK_MIN - 1e-9:
        compliant = False
    status = 'compliant' if compliant else 'non-compliant'
    out['runs'][run_id] = {'tc_id': tc_id, 'max_preheat_ramp': res['max_preheat_ramp'], 'tal_s': res['tal_s'], 'peak_c': res['peak_c'], 'status': status}
    if not compliant:
        out['failing_runs'].append(run_id)

